   const ri=this.nodes?.[t.nodeFrom]?.edges.find(e=>e.to===t.nodeTo)?.ri??t.roadIndex;
   const road=TAIPEI_ROADS[ri];
   if(road){const half=road.width/1.7/2,vehicleHalf=(t.group.userData.width||(t.type?2:.72))/2;lane=Math.min(lane,Math.max(0,half-vehicleHalf-.12));}
