  const driftHeld=!!(this.keys.ControlLeft||this.keys.ControlRight||this.padConnected&&this.padDrift);
  s.brakeHeld=brake&&!gas?s.brakeHeld+dt:0;
  if(this.courierAdvanced&&this.gameState==='PLAYING'&&this.celebrationTime<=0&&!this.isManualShift&&this.currentGear==='D'&&this.isGrounded&&this.carSpeed>=30/3.6&&s.brakeHeld>=.14&&s.cooldown===0){
   s.stopTime=.48;s.stopPending=.75;s.cooldown=1;
   this.courierSkillFeedback('急煞收單！','stop');if(this.courierDrill?.id==='stop')this.courierDrill.phase='braking';
  }
  if(s.stopTime>0){
   if(!brake||gas||!this.isGrounded)s.stopTime=s.stopPending=0;
   else {this.carSpeed=Math.max(0,this.carSpeed-40*dt);this.dashTime=0;this.reverseHold=0;s.stopTime=Math.max(0,s.stopTime-dt);}
  }
  if(this.courierAdvanced&&s.driftHeld&&!driftHeld&&this.isGrounded&&this.driftFactor>.3&&this.carSpeed>3){s.exitTime=.3;this.courierSkillFeedback('甩尾回正！','exit');if(this.courierDrill?.id==='exit')this.courierDrill.phase='exit';}
  s.driftHeld=driftHeld;
  // Exit assistance changes heading before the existing swept collision solver.
  // It never writes a new position or bypasses a wall, ramp or B1 ceiling.
  const heldLeft=this.keys.ControlLeft,heldRight=this.keys.ControlRight,pad=this.padDrift;
  if(s.exitTime>0&&this.isGrounded){this.keys.ControlLeft=this.keys.ControlRight=false;this.padDrift=false;this.quickDriftTime=0;const diff=Math.atan2(Math.sin(this.carRotY-this.heading),Math.cos(this.carRotY-this.heading));if(this.handlingMode!=='ARCADE_V2')this.heading+=diff*(1-Math.exp(-dt*12));}
  const airborne=!this.isGrounded;
  try{old.updateVehiclePhysics.call(this,dt);}finally{this.keys.ControlLeft=heldLeft;this.keys.ControlRight=heldRight;this.padDrift=pad;}
  s.exitTime=Math.max(0,s.exitTime-dt);s.stopPending=Math.max(0,s.stopPending-dt);
  const d=this.courierDrill;
  if(d?.status==='running'){
   if(d.id==='stop'&&d.phase==='braking'&&s.stopPending>0&&this.isGrounded&&Math.abs(this.carSpeed)<1.5&&d.clean)this.finishCourierDrill(true,'完成急煞收單');
   if(d.id==='exit'&&d.phase==='exit'&&s.exitTime===0&&d.clean&&Math.abs(Math.atan2(Math.sin(this.carRotY-this.heading),Math.cos(this.carRotY-this.heading)))<.2)this.finishCourierDrill(true,'完成甩尾回正');
   if(d.id==='hop'&&d.phase==='air'&&airborne&&this.isGrounded&&d.clean)this.finishCourierDrill(true,'完成跳躍穩落');
  }
