  el('skill-feedback').textContent=s.time<s.feedbackUntil?s.feedback:'甩尾 · 飛躍 · 擦身快送';el('skill-feedback').dataset.kind=s.time<s.feedbackUntil?s.kind:'ready';
  el('skill-chain').textContent=this.comboCount>0?'×'+(1+Math.min(10,this.comboCount)*.1).toFixed(1)+' 技巧倍率':'技巧連段';
