   this.game=game;this.grid=grid;this.mode='bundled-fallback';this.manifest=null;this.rows=new Map();
   this.full=new Map();this.lod=new Map();this.pending=new Map();this.fallbackFullCache=new Map();this.fallbackLodCache=new Map();this.failures=0;this.requests=0;this.fallbackActivations=0;this.errors=[];this.lean=grid.buildingsById.size===0;
